import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { actionToUrl, router, urlToAction } from 'kea-router'

import { FEATURE_FLAGS } from 'lib/constants'
import { featureFlagLogic, type FeatureFlagsSet } from 'lib/logic/featureFlagLogic'
import { removeProjectIdIfPresent } from 'lib/utils/kea-router'
import { urls } from 'scenes/urls'

import { getDatasetListUrl } from '../datasets/aiObservabilityDatasetsLogic'

export type OfflineEvaluationsTab = 'experiments' | 'datasets'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface offlineEvaluationsLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    receivedFeatureFlags: boolean // featureFlagLogic
    activeTab: OfflineEvaluationsTab
    datasetsEnabled: boolean
    datasetsOnly: boolean
    offlineEvaluationsEnabled: boolean
    selectedTab: OfflineEvaluationsTab
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface offlineEvaluationsLogicActions {
    ensureAvailableTab: () => {
        value: true
    }
    setActiveTab: (tab: OfflineEvaluationsTab) => {
        tab: OfflineEvaluationsTab
    }
    syncTabFromUrl: (tab: OfflineEvaluationsTab) => {
        tab: OfflineEvaluationsTab
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface offlineEvaluationsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        offlineEvaluationsEnabled: (featureFlags: FeatureFlagsSet) => boolean
        datasetsEnabled: (featureFlags: FeatureFlagsSet) => boolean
        datasetsOnly: (datasetsEnabled: boolean, offlineEvaluationsEnabled: boolean) => boolean
        activeTab: (selectedTab: OfflineEvaluationsTab, datasetsOnly: boolean) => OfflineEvaluationsTab
    }
}

export type offlineEvaluationsLogicType = MakeLogicType<
    offlineEvaluationsLogicValues,
    offlineEvaluationsLogicActions,
    Record<string, any>,
    offlineEvaluationsLogicMeta
>

export const offlineEvaluationsLogic = kea<offlineEvaluationsLogicType>([
    path(['products', 'ai_observability', 'offlineEvaluationsLogic']),
    connect({ values: [featureFlagLogic, ['featureFlags', 'receivedFeatureFlags']] }),
    actions({
        setActiveTab: (tab: OfflineEvaluationsTab) => ({ tab }),
        syncTabFromUrl: (tab: OfflineEvaluationsTab) => ({ tab }),
        ensureAvailableTab: true,
    }),
    reducers({
        selectedTab: [
            'experiments' as OfflineEvaluationsTab,
            {
                setActiveTab: (_, { tab }) => tab,
                syncTabFromUrl: (_, { tab }) => tab,
            },
        ],
    }),
    selectors({
        offlineEvaluationsEnabled: [
            (s) => [s.featureFlags],
            (featureFlags: FeatureFlagsSet): boolean =>
                !!featureFlags[FEATURE_FLAGS.AI_OBSERVABILITY_OFFLINE_EVALUATIONS],
        ],
        datasetsEnabled: [
            (s) => [s.featureFlags],
            (featureFlags: FeatureFlagsSet): boolean => !!featureFlags[FEATURE_FLAGS.LLM_ANALYTICS_DATASETS],
        ],
        datasetsOnly: [
            (s) => [s.datasetsEnabled, s.offlineEvaluationsEnabled],
            (datasetsEnabled: boolean, offlineEvaluationsEnabled: boolean): boolean =>
                datasetsEnabled && !offlineEvaluationsEnabled,
        ],
        activeTab: [
            (s) => [s.selectedTab, s.datasetsOnly],
            (selectedTab: OfflineEvaluationsTab, datasetsOnly: boolean): OfflineEvaluationsTab =>
                datasetsOnly ? 'datasets' : selectedTab,
        ],
    }),
    listeners(({ actions, values }) => ({
        ensureAvailableTab: () => {
            if (
                removeProjectIdIfPresent(router.values.location.pathname) !== urls.aiObservabilityOfflineEvaluations()
            ) {
                return
            }
            actions.syncTabFromUrl(router.values.searchParams.tab === 'datasets' ? 'datasets' : 'experiments')
            if (values.receivedFeatureFlags && values.datasetsOnly && router.values.searchParams.tab !== 'datasets') {
                router.actions.replace(
                    router.values.location.pathname,
                    { ...router.values.searchParams, tab: 'datasets' },
                    router.values.hashParams
                )
            }
        },
        [featureFlagLogic.actionTypes.setFeatureFlags]: () => actions.ensureAvailableTab(),
    })),
    actionToUrl(({ values }) => ({
        setActiveTab: ({ tab }) => [
            values.datasetsOnly || tab === 'datasets'
                ? getDatasetListUrl(
                      removeProjectIdIfPresent(router.values.location.pathname) ===
                          urls.aiObservabilityOfflineEvaluations() && router.values.searchParams.tab !== 'datasets'
                          ? {}
                          : router.values.searchParams
                  )
                : `${urls.aiObservabilityOfflineEvaluations()}?tab=experiments`,
            {},
            router.values.hashParams,
        ],
    })),
    urlToAction(({ actions }) => ({
        [urls.aiObservabilityOfflineEvaluations()]: () => actions.ensureAvailableTab(),
    })),
    afterMount(({ actions }) => actions.ensureAvailableTab()),
])
